#include <iostream>
#include <iomanip>
#include <string>

int main() {
    std::string line;
    std::getline(std::cin, line);  // header
    double peak = 0;
    double worst = 0;
    while (std::getline(std::cin, line)) {
        std::size_t comma = line.find(',');
        if (comma == std::string::npos) {
            continue;
        }
        double p = std::stod(line.substr(comma + 1));
        if (p > peak) {
            peak = p;
        }
        double fall = (peak - p) / peak;
        if (fall > worst) {
            worst = fall;
        }
    }
    std::cout << "Max drawdown: " << std::fixed << std::setprecision(2) << worst * 100 << "%\n";
    return 0;
}

explain.text:
Read the header once, then loop on `std::getline`, skipping any line without a comma. Each close updates the running peak and the worst fall. `std::fixed` with `std::setprecision(2)` prints exactly two decimals.

